import {TODAY,metrics} from './data.js?v=20260920-query';
import {assignTemporaryUnit,confirmRelocation,approveRenovation,approveInspection,confirmReturn} from './renovation-data.js?v=20260920-query';
import {poolTable} from './renovation.js?v=20260920-query';
import {e,date,icon,field} from './ui.js?v=20260920-query';

export function renovationAction(action,id,ctx){const {data:d,openModal,toast,render}=ctx;
 if(action==='pool-modal'){openModal('وحدات السكن المؤقت',`<p class="modal-description">وحدات مخصصة للانتقال المؤقت، مع عرض التخصيص الحالي لكل أسرة.</p>${poolTable(d)}`,'','',true);return true;}
 if(action==='renovation-assess'){const p=d.renovation.plans.find(p=>p.id===id);if(p.status==='PLANNING'){p.status='ASSESSMENT';p.progress=5;render();toast('بدأ تقييم المبنى وتحديد نطاق العمل.');}return true;}
 const r=d.renovation.residents.find(r=>r.id===id),t=r?d.tenants.find(t=>t.id===r.tenantId):null;
 if(action==='relocation-assign'){const original=d.units.find(u=>u.id===r.originalUnitId),pool=d.renovation.pool.filter(p=>p.state==='READY'&&d.units.find(u=>u.id===p.unitId).bedrooms>=original.bedrooms);openModal('تخصيص وحدة بديلة',`<input type="hidden" name="id" value="${e(id)}"/><div class="confirmation">${icon('home')}<div><strong>${e(t.name)} · ${r.originalUnitId}</strong><p>${t.family} أفراد · العودة المتوقعة ${date(r.expectedReturn)}</p></div></div>${field('الوحدة البديلة المتاحة *',`<select name="unitId" required>${pool.map(p=>{const u=d.units.find(u=>u.id===p.unitId);return `<option value="${p.unitId}">${p.unitId} · ${u.bedrooms===2?'غرفتا نوم':'غرفة نوم'} · ${u.area} م²</option>`;}).join('')}</select>`)}<p class="small muted" style="margin-top:15px">الوحدات المعروضة جاهزة ولا تقل في عدد الغرف عن الوحدة الأصلية. يبقى عقد الأسرة مرتبطاً بوحدتها الأصلية.</p>`,'relocation-assign-form','تأكيد تخصيص الوحدة');return true;}
 if(action==='relocation-move'||action==='relocation-return'){const returning=action==='relocation-return';openModal(returning?'اعتماد عودة المستأجر':'تأكيد الانتقال المؤقت',`<input type="hidden" name="id" value="${e(id)}"/><div class="confirmation">${icon(returning?'check':'route')}<div><strong>${e(t.name)}</strong><p>من ${returning?r.temporaryUnitId:r.originalUnitId} إلى ${returning?r.originalUnitId:r.temporaryUnitId}</p></div></div><label style="display:flex;gap:10px;align-items:center;font-size:14px"><input type="checkbox" required/>${returning?'تم فحص الوحدة الأصلية وتسليمها للأسرة واستلام الوحدة المؤقتة.':'تم تسليم الوحدة البديلة وتأكيد انتقال الأسرة إليها.'}</label><p class="small muted" style="margin-top:15px">${returning?'ستتحرر الوحدة المؤقتة ويُحدّث سجل المستأجر ومؤشر الأسر العائدة.':'ستتغير حالة الوحدة البديلة من محجوزة إلى مستخدمة، مع تحديث تاريخ الانتقال.'}</p>`,returning?'relocation-return-form':'relocation-move-form',returning?'اعتماد العودة':'تأكيد الانتقال');return true;}
 if(action==='renovation-complete'||action==='renovation-inspect'){const inspect=action==='renovation-inspect';openModal(inspect?'اعتماد فحص الجودة':'اعتماد اكتمال أعمال الصيانة',`<input type="hidden" name="id" value="${e(id)}"/><div class="confirmation">${icon(inspect?'shield':'building')}<div><strong>برنامج تجديد ${e(id)}</strong><p>${inspect?'تأكيد جاهزية الوحدات الأصلية للسكن.':'نقل المبنى من تنفيذ الأعمال إلى فحص الجودة.'}</p></div></div><label style="display:flex;align-items:center;gap:10px;font-size:14px"><input type="checkbox" required/>${inspect?'اجتازت الوحدات الأصلية فحص الجودة وأصبحت آمنة وجاهزة لعودة الأسر.':'تمت مراجعة نطاق العمل وتوثيق اكتمال أعمال التجديد.'}</label><p class="small muted" style="margin-top:15px">${inspect?'ستظهر الأسر المنقولة بحالة جاهزة للعودة. اعتماد العودة يتم لكل أسرة على حدة.':'ستصبح حالة المبنى جاهزاً للفحص، وتظل الأسر في وحداتها المؤقتة حتى اعتماد الجودة.'}</p>`,inspect?'renovation-inspect-form':'renovation-complete-form',inspect?'اعتماد فحص الجودة':'اعتماد اكتمال الصيانة');return true;}
 if(action==='release-temporary'){const p=d.renovation.pool.find(p=>p.unitId===id);if(p?.state!=='READY'){toast('لا يمكن تحرير وحدة مستخدمة أو محجوزة.');return true;}openModal('إعادة الوحدة إلى مخزون التأجير',`<input type="hidden" name="id" value="${e(id)}"/><p>الوحدة <span class="ltr">${e(id)}</span> جاهزة ولا توجد أسرة تقيم فيها حالياً.</p><p class="small muted" style="margin-top:12px">سيُلغى تخصيصها للسكن المؤقت وتصبح متاحة لطلبات الإيجار، ويقل عدد الوحدات الجاهزة في مخزون الانتقال.</p>`,'release-temporary-form','إتاحتها للتأجير');return true;}
 return false;
}
export function renovationSubmit(form,values,ctx){const {data:d,error,activity,refreshWithToast}=ctx;const handlers={'relocation-assign-form':()=>{const r=assignTemporaryUnit(d,values.id,values.unitId);return ['تم تخصيص الوحدة البديلة بنجاح.',r.buildingId,r.originalUnitId];},'relocation-move-form':()=>{const r=confirmRelocation(d,values.id);return ['تم نقل المستأجر وتحديث مخزون السكن المؤقت.',r.buildingId,r.originalUnitId];},'renovation-complete-form':()=>{const p=approveRenovation(d,values.id);return ['تم اعتماد اكتمال الصيانة. المبنى جاهز للفحص.',p.id,p.type];},'renovation-inspect-form':()=>{const p=approveInspection(d,values.id);return ['اجتاز المبنى فحص الجودة وأصبحت الأسر جاهزة للعودة.',p.id,p.type];},'relocation-return-form':()=>{const r=confirmReturn(d,values.id);return ['تمت إعادة المستأجر وتحرير الوحدة المؤقتة.',r.buildingId,r.originalUnitId];},'release-temporary-form':()=>{const p=d.renovation.pool.find(p=>p.unitId===values.id);if(!p||p.state!=='READY')throw new Error('الوحدة غير جاهزة للتحرير.');d.units.find(u=>u.id===values.id).usageType='RENTAL';d.renovation.pool=d.renovation.pool.filter(p=>p.unitId!==values.id);return ['أصبحت الوحدة متاحة للتأجير.','',values.id];}};
 if(!handlers[form])return false;
 try{const [msg,id,detail]=handlers[form]();activity(msg,detail,id?'/renovation/'+id:'/renovation','home');refreshWithToast(msg);}catch(err){error(err.message);}return true;
}
